class Qwen3VLConfig(PretrainedConfig):
    r"""
    This is the configuration class to store the configuration of a [`Qwen3VLModel`].
    It is used to instantiate a Qwen3-VL model according to the specified arguments,
    defining the model architecture.

    Instantiating a configuration with the defaults will yield a configuration
    similar to that of Qwen/Qwen3-VL-8B-Instruct.

    Args:
        text_config (`dict`, *optional*):
            Configuration of the text model.
        vision_config (`dict`, *optional*):
            Configuration of the vision model.
        image_token_id (`int`, *optional*, defaults to 151655):
            Token id of the image placeholder token.
        video_token_id (`int`, *optional*, defaults to 151656):
            Token id of the video placeholder token.
        vision_start_token_id (`int`, *optional*, defaults to 151652):
            Token id of the vision start token.
        vision_end_token_id (`int`, *optional*, defaults to 151653):
            Token id of the vision end token.
        use_fava (`bool`, *optional*, defaults to `False`):
            Whether to enable FaVA forensic artifact tokens.
        fava_token_id (`int`, *optional*):
            Token id of the FaVA placeholder token.
    """

    model_type = "qwen3_vl"
    sub_configs = {"vision_config": Qwen3VLVisionConfig, "text_config": Qwen3VLTextConfig}
    keys_to_ignore_at_inference = ["past_key_values"]

    def __init__(
        self,
        text_config=None,
        vision_config=None,
        image_token_id=151655,
        video_token_id=151656,
        vision_start_token_id=151652,
        vision_end_token_id=151653,
        tie_word_embeddings=False,

        # ===== FaVA config =====
        use_fava=False,
        fava_token="<|fava_pad|>",
        fava_token_id=None,
        fava_num_frames=16,
        fava_image_size=224,
        fava_patch_size=16,
        fava_num_bands=4,
        fava_token_dim=256,
        fava_num_tokens=128,
        fava_num_query_blocks=2,
        fava_num_heads=8,
        fava_top_k=1024,
        fava_peak_selection="topk",
        fava_projector_type="linear",
        freeze_fava=True,

        use_cls_head=False,
        cls_num_labels=2,
        cls_loss_weight=1.0,
        lm_loss_weight=1.0,
        cls_dropout=0.1,
        cls_pooling="pre_answer",

        #loss
        use_semantic_decorr_loss=False,
        semantic_decorr_loss_weight=0.0,
        semantic_decorr_max_video_tokens=1024,
        semantic_decorr_detach_video=True,

        use_consistency_loss=False,
        consistency_loss_weight=0.0,
        consistency_temperature=1.0,
        answer_real_token_id=None,
        answer_fake_token_id=None,

        **kwargs,
    ):
        if isinstance(vision_config, dict):
            self.vision_config = self.sub_configs["vision_config"](**vision_config)
        elif vision_config is None:
            self.vision_config = self.sub_configs["vision_config"]()

        if isinstance(text_config, dict):
            self.text_config = self.sub_configs["text_config"](**text_config)
        elif text_config is None:
            self.text_config = self.sub_configs["text_config"]()

        self.image_token_id = image_token_id
        self.video_token_id = video_token_id
        self.vision_start_token_id = vision_start_token_id
        self.vision_end_token_id = vision_end_token_id

        # ===== FaVA config =====
        self.use_fava = use_fava
        self.fava_token = fava_token
        self.fava_token_id = fava_token_id
        self.fava_num_frames = fava_num_frames
        self.fava_image_size = fava_image_size
        self.fava_patch_size = fava_patch_size
        self.fava_num_bands = fava_num_bands
        self.fava_token_dim = fava_token_dim
        self.fava_num_tokens = fava_num_tokens
        self.fava_num_query_blocks = fava_num_query_blocks
        self.fava_num_heads = fava_num_heads
        self.fava_top_k = fava_top_k
        self.fava_peak_selection = fava_peak_selection
        self.fava_projector_type = fava_projector_type
        self.freeze_fava = freeze_fava

        self.use_cls_head = use_cls_head
        self.cls_num_labels = cls_num_labels
        self.cls_loss_weight = cls_loss_weight
        self.lm_loss_weight = lm_loss_weight
        self.cls_dropout = cls_dropout
        self.cls_pooling = cls_pooling

        #loss
        self.use_semantic_decorr_loss = use_semantic_decorr_loss
        self.semantic_decorr_loss_weight = semantic_decorr_loss_weight
        self.semantic_decorr_max_video_tokens = semantic_decorr_max_video_tokens
        self.semantic_decorr_detach_video = semantic_decorr_detach_video

        self.use_consistency_loss = use_consistency_loss
        self.consistency_loss_weight = consistency_loss_weight
        self.consistency_temperature = consistency_temperature
        self.answer_real_token_id = answer_real_token_id
        self.answer_fake_token_id = answer_fake_token_id

        super().__init__(**kwargs, tie_word_embeddings=tie_word_embeddings)


